<?php
namespace Dth\Crm\Filament\Resources;
use Dth\Crm\Models\Contact; use Dth\Crm\Filament\Navigation\CrmNavigationGroup; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Schemas\Components\Section; use Filament\Forms\Components\{TextInput,Select,DatePicker}; use Filament\Tables\Table; use Filament\Tables\Columns\TextColumn; use Filament\Actions;
class PersonalContactResource extends Resource {protected static ?string $model=Contact::class;protected static string|\BackedEnum|null $navigationIcon='heroicon-o-user';protected static string|\UnitEnum|null $navigationGroup=CrmNavigationGroup::Crm;protected static ?int $navigationSort=10;public static function getNavigationLabel():string{return \Dth\Crm\Support\UiText::get('navigation.personal_contacts','Personal contacts',context:'navigation');}public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{return parent::getEloquentQuery()->where('type','personal');}
 public static function form(Schema $s):Schema{return $s->components([Section::make('Thông tin liên hệ')->schema([TextInput::make('display_name')->label('Họ và tên')->required(),TextInput::make('email')->email()->label('Email'),TextInput::make('phone')->tel()->label('Điện thoại'),TextInput::make('source')->label('Nguồn'),TextInput::make('profile.occupation')->label('Nghề nghiệp'),DatePicker::make('profile.date_of_birth')->label('Ngày sinh'),Select::make('profile.gender')->options(['male'=>'Nam','female'=>'Nữ','other'=>'Khác']),TextInput::make('profile.province')->label('Tỉnh/Thành'),TextInput::make('profile.service_interest')->label('Dịch vụ quan tâm'),TextInput::make('profile.expected_budget')->numeric()->label('Ngân sách dự kiến')])->columns(2)]);}
 public static function table(Table $t):Table{return $t->columns([TextColumn::make('contact_code')->label('Mã')->searchable(),TextColumn::make('display_name')->label('Họ và tên')->searchable(),TextColumn::make('email')->searchable(),TextColumn::make('phone')->searchable(),TextColumn::make('personalProfile.occupation')->label('Nghề nghiệp'),TextColumn::make('source')->label('Nguồn')])->recordActions([Actions\EditAction::make(),Actions\DeleteAction::make()])->bulkActions([Actions\BulkActionGroup::make([Actions\DeleteBulkAction::make()->authorizeIndividualRecords()])]);}
 public static function getPages():array{return ['index'=>PersonalContactResource\Pages\ListPersonalContacts::route('/'),'create'=>PersonalContactResource\Pages\CreatePersonalContact::route('/create'),'edit'=>PersonalContactResource\Pages\EditPersonalContact::route('/{record}/edit')];}}
